cat > src/params.rs <<'EOF'
//! Typed access to the members of a command object (SPEC.md section 1).
//!
//! A `null` member counts as absent. Handlers first call [`Params::require`]
//! and only then the typed getters, which gives the check order of section 2.

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Code, Error, Result};

#[derive(Clone, Copy)]
pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|value| !value.is_null())
    }

    pub fn has(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    /// Fails with `MissingParameter` for the first of `names` that is absent.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| !self.has(name)) {
            Some(name) => Err(missing(name)),
            None => Ok(()),
        }
    }

    /// Names of the non-null members, for rejecting unknown attributes.
    pub fn names(&self) -> impl Iterator<Item = &'a str> {
        self.0.iter().filter(|(_, v)| !v.is_null()).map(|(k, _)| k.as_str())
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.typed(name, "a string", Value::as_str)
    }

    pub fn require_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?.ok_or_else(|| missing(name))
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.typed(name, "a boolean", Value::as_bool)
    }

    /// An integer within `range`; `30.0`, `3e1` and `"30"` are not integers.
    pub fn integer(&self, name: &str, range: RangeInclusive<u64>) -> Result<Option<u64>> {
        let value = self.typed(name, "an integer", Value::as_u64)?;
        match value {
            Some(n) if !range.contains(&n) => Err(invalid(format!(
                "{name} must be between {} and {}",
                range.start(),
                range.end()
            ))),
            other => Ok(other),
        }
    }

    pub fn require_integer(&self, name: &str, range: RangeInclusive<u64>) -> Result<u64> {
        self.integer(name, range)?.ok_or_else(|| missing(name))
    }

    /// A string of 1 to `max` characters from `A-Z a-z 0-9 _ -`.
    pub fn id_string(&self, name: &str, max: usize) -> Result<Option<&'a str>> {
        match self.string(name)? {
            Some(s) if !is_name_chars(s) || s.is_empty() || s.len() > max => Err(invalid(format!(
                "{name} must be 1 to {max} characters from A-Z a-z 0-9 _ -"
            ))),
            other => Ok(other),
        }
    }

    pub fn object(&self, name: &str) -> Result<Option<Params<'a>>> {
        self.typed(name, "an object", |v| v.as_object().map(Params::new))
    }

    fn typed<T>(
        &self,
        name: &str,
        expected: &str,
        convert: impl FnOnce(&'a Value) -> Option<T>,
    ) -> Result<Option<T>> {
        match self.get(name) {
            None => Ok(None),
            Some(value) => convert(value)
                .map(Some)
                .ok_or_else(|| invalid(format!("{name} must be {expected}"))),
        }
    }
}

/// True if every character is one of `A-Z a-z 0-9 _ -`.
pub fn is_name_chars(s: &str) -> bool {
    s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

pub fn missing(name: &str) -> Error {
    Error::new(Code::MissingParameter, format!("{name} is required"))
}

pub fn invalid(message: impl Into<String>) -> Error {
    Error::new(Code::InvalidParameterValue, message)
}
