//! Command dispatch and the process-wide state (clock, queues, counters).

use serde_json::{Map, Value, json};

use crate::error::{Code, Error, Result};
use crate::params::Params;

/// The members of a success response besides `ok`.
pub type Reply = Map<String, Value>;

#[derive(Default)]
pub struct Service {
    now: u64,
}

impl Service {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one input line (without its `\n`) and returns the response line,
    /// also without `\n`.
    pub fn handle_line(&mut self, line: &[u8]) -> String {
        let response = match self.execute(line) {
            Ok(mut reply) => {
                reply.insert("ok".into(), Value::Bool(true));
                Value::Object(reply)
            }
            Err(error) => json!({
                "ok": false,
                "error": {"code": error.code.as_str(), "message": error.message},
            }),
        };
        response.to_string()
    }

    fn execute(&mut self, line: &[u8]) -> Result<Reply> {
        let request = |message: &str| Error::new(Code::InvalidRequest, message);
        let text = std::str::from_utf8(line).map_err(|_| request("line is not valid UTF-8"))?;
        let value: Value = serde_json::from_str(text).map_err(|e| request(&e.to_string()))?;
        let Value::Object(members) = value else {
            return Err(request("line is not a JSON object"));
        };
        let Some(Value::String(command)) = members.get("Command") else {
            return Err(request("Command must be a string"));
        };
        let params = Params::new(&members);
        match command.as_str() {
            "Tick" => self.tick(params),
            other => Err(request(&format!("unknown command {other:?}"))),
        }
    }

    fn tick(&mut self, params: Params) -> Result<Reply> {
        params.require(&["Seconds"])?;
        let seconds = params.require_integer("Seconds", 0..=1_209_600)?;
        self.now += seconds;
        Ok(reply([("Now", json!(self.now))]))
    }
}

pub fn reply<const N: usize>(members: [(&str, Value); N]) -> Reply {
    members.into_iter().map(|(k, v)| (k.to_owned(), v)).collect()
}
EOF
cat > src/main.rs <<'EOF'
use std::io::{self, BufRead, Write};

use miniq::service::Service;

fn main() -> io::Result<()> {
    let mut input = io::stdin().lock();
    let mut output = io::stdout().lock();
    let mut service = Service::new();
    let mut line = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        let response = service.handle_line(&line);
        writeln!(output, "{response}")?;
        output.flush()?;
    }
}
EOF
