#![allow(dead_code)]
use miniq::service::Service;
use serde_json::Value;

/// Sends each line to a fresh-or-given service and parses the responses.
pub fn run(service: &mut Service, line: &str) -> Value {
    serde_json::from_str(&service.handle_line(line.as_bytes())).expect("response is JSON")
}

pub fn ok(service: &mut Service, line: &str) -> Value {
    let response = run(service, line);
    assert_eq!(response["ok"], true, "{line} -> {response}");
    response
}

/// Asserts a failure with the given error code and returns nothing else.
pub fn fails(service: &mut Service, line: &str, code: &str) {
    let response = run(service, line);
    assert_eq!(response["ok"], false, "{line} -> {response}");
    assert_eq!(response["error"]["code"], code, "{line} -> {response}");
}
EOF
cat > tests/protocol.rs <<'EOF'
mod common;

use std::io::Write;
use std::process::{Command, Stdio};

use common::{fails, ok, run};
use miniq::service::Service;
use serde_json::json;

#[test]
fn malformed_lines_are_invalid_requests() {
    let mut s = Service::new();
    for line in ["", "   ", "nope", "[]", "{}", r#"{"Command": 3}"#, r#"{"Command": "Nope"}"#] {
        fails(&mut s, line, "InvalidRequest");
    }
    let response = s.handle_line(b"{\"Command\": \"Tick\", \"Seconds\": 1}\xff");
    assert!(response.contains("InvalidRequest"));
}

#[test]
fn tick_advances_the_clock() {
    let mut s = Service::new();
    assert_eq!(ok(&mut s, r#"{"Command":"Tick","Seconds":5}"#), json!({"ok": true, "Now": 5}));
    assert_eq!(ok(&mut s, r#"{"Command":"Tick","Seconds":0,"Extra":1}"#)["Now"], 5);
}

#[test]
fn parameter_checks_follow_the_spec_order() {
    let mut s = Service::new();
    fails(&mut s, r#"{"Command":"Tick"}"#, "MissingParameter");
    fails(&mut s, r#"{"Command":"Tick","Seconds":null}"#, "MissingParameter");
    for bad in ["30.0", "3e1", r#""30""#, "-1", "1209601", "true"] {
        fails(&mut s, &format!(r#"{{"Command":"Tick","Seconds":{bad}}}"#), "InvalidParameterValue");
    }
    assert_eq!(run(&mut s, r#"{"Command":"Tick","Seconds":1209600}"#)["Now"], 1209600);
}

#[test]
fn binary_answers_every_line_including_an_unterminated_last_one() {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(b"{\"Command\":\"Tick\",\"Seconds\":2}\n\n{\"Command\":\"Tick\",\"Seconds\":3}")
        .unwrap();
    let output = child.wait_with_output().unwrap();
    assert!(output.status.success());
    let lines: Vec<serde_json::Value> = String::from_utf8(output.stdout)
        .unwrap()
        .lines()
        .map(|l| serde_json::from_str(l).unwrap())
        .collect();
    assert_eq!(lines.len(), 3);
    assert_eq!(lines[0]["Now"], 2);
    assert_eq!(lines[1]["error"]["code"], "InvalidRequest");
    assert_eq!(lines[2]["Now"], 5);
}
EOF
