//! A queue, its attributes and its messages (SPEC.md section 4).

use std::collections::{BTreeMap, HashMap, HashSet};

use crate::error::Result;
use crate::params::{Params, invalid, is_name_chars};

pub const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW: u64 = 300;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: u64,
    pub delay_seconds: u64,
    pub retention_seconds: u64,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

/// The attributes named in a request; `None` means "not given".
#[derive(Debug, Default)]
pub struct AttributeUpdate {
    pub visibility_timeout: Option<u64>,
    pub delay_seconds: Option<u64>,
    pub retention_seconds: Option<u64>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u64>,
}

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

impl AttributeUpdate {
    /// Checks names, types and ranges of every attribute (section 2, step 3).
    pub fn parse(attributes: Params) -> Result<Self> {
        if let Some(name) = attributes.names().find(|n| !ATTRIBUTE_NAMES.contains(n)) {
            return Err(invalid(format!("unknown attribute {name}")));
        }
        Ok(Self {
            visibility_timeout: attributes.integer("VisibilityTimeout", 0..=43_200)?,
            delay_seconds: attributes.integer("DelaySeconds", 0..=900)?,
            retention_seconds: attributes.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: attributes.boolean("Fifo")?,
            content_based_deduplication: attributes.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: attributes.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: attributes.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    /// True if exactly one half of the dead-letter configuration is given.
    pub fn has_half_dead_letter(&self) -> bool {
        self.dead_letter_queue.is_some() != self.max_receive_count.is_some()
    }
}

impl Attributes {
    /// Overwrites the attributes present in `update`; `Fifo` is not touched.
    pub fn apply(&mut self, update: AttributeUpdate) {
        let AttributeUpdate {
            visibility_timeout,
            delay_seconds,
            retention_seconds,
            fifo: _,
            content_based_deduplication,
            dead_letter_queue,
            max_receive_count,
        } = update;
        self.visibility_timeout = visibility_timeout.unwrap_or(self.visibility_timeout);
        self.delay_seconds = delay_seconds.unwrap_or(self.delay_seconds);
        self.retention_seconds = retention_seconds.unwrap_or(self.retention_seconds);
        self.content_based_deduplication =
            content_based_deduplication.unwrap_or(self.content_based_deduplication);
        if let (Some(queue), Some(max_receive_count)) = (dead_letter_queue, max_receive_count) {
            self.dead_letter = Some(DeadLetter { queue, max_receive_count });
        }
    }
}

/// 1 to 80 name characters, or 1 to 75 of them followed by `.fifo`.
pub fn is_valid_queue_name(name: &str) -> bool {
    let stem = name.strip_suffix(".fifo").unwrap_or(name);
    name.len() <= 80 && !stem.is_empty() && is_name_chars(stem)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Delayed,
    InFlight,
    Visible,
}

#[derive(Debug, Clone)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u64,
    pub first_received_at: Option<u64>,
    pub group_id: Option<String>,
    pub sequence: Option<u64>,
    /// The message is hidden (delayed or in flight) while `now < hidden_until`.
    hidden_until: u64,
    /// Latest receipt handle; it only matters while the message is in flight.
    handle: Option<u64>,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        match (now < self.hidden_until, self.handle) {
            (false, _) => State::Visible,
            (true, Some(_)) => State::InFlight,
            (true, None) => State::Delayed,
        }
    }

    /// Restarts the in-flight period at `now` for `visibility` seconds.
    pub fn set_visibility(&mut self, now: u64, visibility: u64) {
        self.hidden_until = now + visibility;
    }
}

/// Every receipt handle ever issued, as the (queue uid, arrival key) it was issued for.
#[derive(Default)]
pub struct Handles {
    issued: Vec<(u64, u64)>,
}

impl Handles {
    fn issue(&mut self, queue_uid: u64, arrival: u64) -> u64 {
        self.issued.push((queue_uid, arrival));
        self.issued.len() as u64
    }

    /// Resolves `r-<n>` (canonical decimal, already issued) to its number and origin.
    pub fn resolve(&self, text: &str) -> Option<(u64, (u64, u64))> {
        let digits = text.strip_prefix("r-")?;
        if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        let n: u64 = digits.parse().ok()?;
        let origin = *self.issued.get(usize::try_from(n.checked_sub(1)?).ok()?)?;
        Some((n, origin))
    }
}

/// What `receive` hands back for one delivered message.
pub struct Delivery {
    pub message: Message,
    pub handle: u64,
}

struct Dedup {
    accepted_at: u64,
    message_id: u64,
    sequence: Option<u64>,
}

pub struct Queue {
    uid: u64,
    pub attributes: Attributes,
    /// Messages keyed by arrival number, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    next_arrival: u64,
    next_sequence: u64,
    dedup: HashMap<String, Dedup>,
    /// The `(now, retention)` for which retention was last enforced.
    expired_for: Option<(u64, u64)>,
}

impl Queue {
    pub fn new(uid: u64, attributes: Attributes) -> Self {
        Self {
            uid,
            attributes,
            messages: BTreeMap::new(),
            next_arrival: 0,
            next_sequence: 1,
            dedup: HashMap::new(),
            expired_for: None,
        }
    }

    /// Removes messages past retention. Skipped when neither the clock nor the
    /// retention changed since the last call, so sending stays O(1).
    pub fn expire(&mut self, now: u64) {
        let retention = self.attributes.retention_seconds;
        if self.expired_for == Some((now, retention)) {
            return;
        }
        self.messages.retain(|_, m| now < m.sent_at + retention);
        self.expired_for = Some((now, retention));
    }

    pub fn counts(&self, now: u64) -> [usize; 3] {
        let mut counts = [0; 3];
        for message in self.messages.values() {
            counts[message.state(now) as usize] += 1;
        }
        counts
    }

    pub fn is_full(&self) -> bool {
        self.messages.len() >= MAX_MESSAGES
    }

    pub fn purge(&mut self) {
        self.messages.clear();
    }

    /// The `(MessageId, SequenceNumber)` of the message that opened a still-open window for `id`.
    pub fn duplicate_of(&self, dedup_id: &str, now: u64) -> Option<(u64, Option<u64>)> {
        let seen = self.dedup.get(dedup_id)?;
        (now - seen.accepted_at < DEDUP_WINDOW).then_some((seen.message_id, seen.sequence))
    }

    /// Appends a new message; a FIFO queue also records `dedup_id` and returns the sequence number.
    pub fn add(
        &mut self,
        now: u64,
        id: u64,
        body: String,
        delay: u64,
        group_id: Option<String>,
        dedup_id: Option<String>,
    ) -> Option<u64> {
        let sequence = self.attributes.fifo.then(|| self.take_sequence());
        if let Some(dedup_id) = dedup_id {
            let entry = Dedup { accepted_at: now, message_id: id, sequence };
            self.dedup.insert(dedup_id, entry);
        }
        let message = Message {
            id,
            body,
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group_id,
            sequence,
            hidden_until: now + delay,
            handle: None,
        };
        self.push(message);
        sequence
    }

    /// Accepts a message moved from another queue, ignoring the size limit and deduplication.
    pub fn add_dead_letter(&mut self, now: u64, mut message: Message) {
        if now >= message.sent_at + self.attributes.retention_seconds {
            return;
        }
        message.receive_count = 0;
        message.first_received_at = None;
        message.hidden_until = 0;
        message.handle = None;
        message.sequence = self.attributes.fifo.then(|| self.take_sequence());
        self.push(message);
    }

    fn take_sequence(&mut self) -> u64 {
        self.next_sequence += 1;
        self.next_sequence - 1
    }

    fn push(&mut self, message: Message) {
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
    }

    /// Delivers up to `max` eligible messages. Messages that exceeded the
    /// dead-letter threshold are removed and returned for the caller to move.
    pub fn receive(
        &mut self,
        now: u64,
        max: usize,
        visibility: u64,
        handles: &mut Handles,
    ) -> (Vec<Delivery>, Vec<Message>) {
        let threshold = self.attributes.dead_letter.as_ref().map(|d| d.max_receive_count);
        let mut deliveries = Vec::new();
        let mut dead_keys = Vec::new();
        // Groups with an earlier message that is still in the queue.
        let mut occupied: HashSet<String> = HashSet::new();
        for (&arrival, message) in &mut self.messages {
            if deliveries.len() == max {
                break;
            }
            if let Some(group) = &message.group_id {
                if occupied.contains(group) {
                    continue;
                }
            }
            let visible = message.state(now) == State::Visible;
            if visible && threshold.is_some_and(|t| message.receive_count >= t) {
                dead_keys.push(arrival);
                continue;
            }
            if let Some(group) = &message.group_id {
                occupied.insert(group.clone());
            }
            if !visible {
                continue;
            }
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            let handle = handles.issue(self.uid, arrival);
            message.handle = Some(handle);
            message.hidden_until = now + visibility;
            deliveries.push(Delivery { message: message.clone(), handle });
        }
        let dead = dead_keys.iter().filter_map(|key| self.messages.remove(key)).collect();
        (deliveries, dead)
    }

    /// The message that `handle` (issued for `origin`) still designates, if it is in flight.
    pub fn in_flight(&self, now: u64, handle: u64, origin: (u64, u64)) -> Option<u64> {
        let (uid, arrival) = origin;
        let message = self.messages.get(&arrival)?;
        let current = uid == self.uid
            && message.handle == Some(handle)
            && message.state(now) == State::InFlight;
        current.then_some(arrival)
    }

    pub fn message_mut(&mut self, arrival: u64) -> Option<&mut Message> {
        self.messages.get_mut(&arrival)
    }

    pub fn remove(&mut self, arrival: u64) {
        self.messages.remove(&arrival);
    }
}
