    pub fn resolve(&self, text: &str) -> Option<(u64, (u64, u64))> {
        let digits = text.strip_prefix("r-")?;
        if digits.starts_with('0') || !digits.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        let n: u64 = digits.parse().ok()?;
        let origin = *self.issued.get(usize::try_from(n.checked_sub(1)?).ok()?)?;
        Some((n, origin))
    }
}

/// What `receive` hands back for one delivered message.
pub struct Delivery {
    pub message: Message,
    pub handle: u64,
}

struct Dedup {
    accepted_at: u64,
    message_id: u64,
    sequence: Option<u64>,
}

pub struct Queue {
    uid: u64,
    pub attributes: Attributes,
    /// Messages keyed by arrival number, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    next_arrival: u64,
    next_sequence: u64,
    dedup: HashMap<String, Dedup>,
    /// The `(now, retention)` for which retention was last enforced.
    expired_for: Option<(u64, u64)>,
}

impl Queue {
    pub fn new(uid: u64, attributes: Attributes) -> Self {
        Self {
            uid,
            attributes,
            messages: BTreeMap::new(),
            next_arrival: 0,
            next_sequence: 1,
            dedup: HashMap::new(),
            expired_for: None,
        }
    }

    /// Removes messages past retention. Skipped when neither the clock nor the
    /// retention changed since the last call, so sending stays O(1).
    pub fn expire(&mut self, now: u64) {
        let retention = self.attributes.retention_seconds;
        if self.expired_for == Some((now, retention)) {
            return;
        }
        self.messages.retain(|_, m| now < m.sent_at + retention);
        self.expired_for = Some((now, retention));
    }

    pub fn counts(&self, now: u64) -> [usize; 3] {
        let mut counts = [0; 3];
        for message in self.messages.values() {
            counts[message.state(now) as usize] += 1;
        }
        counts
    }

    pub fn is_full(&self) -> bool {
        self.messages.len() >= MAX_MESSAGES
    }

    pub fn purge(&mut self) {
        self.messages.clear();
    }

    /// The `(MessageId, SequenceNumber)` of the message that opened a still-open window for `id`.
    pub fn duplicate_of(&self, dedup_id: &str, now: u64) -> Option<(u64, Option<u64>)> {
        let seen = self.dedup.get(dedup_id)?;
        (now - seen.accepted_at < DEDUP_WINDOW).then_some((seen.message_id, seen.sequence))
    }

    /// Appends a new message; a FIFO queue also records `dedup_id` and returns the sequence number.
    pub fn add(
        &mut self,
        now: u64,
        id: u64,
        body: String,
        delay: u64,
        group_id: Option<String>,
        dedup_id: Option<String>,
    ) -> Option<u64> {
        let sequence = self.attributes.fifo.then(|| self.take_sequence());
        if let Some(dedup_id) = dedup_id {
            let entry = Dedup { accepted_at: now, message_id: id, sequence };
            self.dedup.insert(dedup_id, entry);
        }
        let message = Message {
            id,
            body,
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group_id,
            sequence,
            hidden_until: now + delay,
            handle: None,
        };
        self.push(message);
        sequence
    }

    /// Accepts a message moved from another queue, ignoring the size limit and deduplication.
    pub fn add_dead_letter(&mut self, now: u64, mut message: Message) {
        if now >= message.sent_at + self.attributes.retention_seconds {
            return;
        }
        message.receive_count = 0;
        message.first_received_at = None;
        message.hidden_until = 0;
        message.handle = None;
        message.sequence = self.attributes.fifo.then(|| self.take_sequence());
        self.push(message);
    }

    fn take_sequence(&mut self) -> u64 {
        self.next_sequence += 1;
        self.next_sequence - 1
    }

    fn push(&mut self, message: Message) {
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
    }

    /// Delivers up to `max` eligible messages. Messages that exceeded the
    /// dead-letter threshold are removed and returned for the caller to move.
    pub fn receive(
        &mut self,
        now: u64,
        max: usize,
        visibility: u64,
        handles: &mut Handles,
    ) -> (Vec<Delivery>, Vec<Message>) {
        let threshold = self.attributes.dead_letter.as_ref().map(|d| d.max_receive_count);
        let mut deliveries = Vec::new();
        let mut dead_keys = Vec::new();
        // Groups with an earlier message that is still in the queue.
        let mut occupied: HashSet<String> = HashSet::new();
        for (&arrival, message) in &mut self.messages {
            if deliveries.len() == max {
                break;
            }
            if let Some(group) = &message.group_id {
                if occupied.contains(group) {
                    continue;
                }
            }
            let visible = message.state(now) == State::Visible;
            if visible && threshold.is_some_and(|t| message.receive_count >= t) {
                dead_keys.push(arrival);
                continue;
            }
            if let Some(group) = &message.group_id {
                occupied.insert(group.clone());
            }
            if !visible {
                continue;
            }
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            let handle = handles.issue(self.uid, arrival);
            message.handle = Some(handle);
            message.hidden_until = now + visibility;
            deliveries.push(Delivery { message: message.clone(), handle });
        }
        let dead = dead_keys.iter().filter_map(|key| self.messages.remove(key)).collect();
        (deliveries, dead)
    }

    /// The message that `handle` (issued for `origin`) still designates, if it is in flight.
    pub fn in_flight(&self, now: u64, handle: u64, origin: (u64, u64)) -> Option<u64> {
        let (uid, arrival) = origin;
        let message = self.messages.get(&arrival)?;
        let current = uid == self.uid
            && message.handle == Some(handle)
            && message.state(now) == State::InFlight;
        current.then_some(arrival)
    }

    pub fn message_mut(&mut self, arrival: u64) -> Option<&mut Message> {
        self.messages.get_mut(&arrival)
    }

    pub fn remove(&mut self, arrival: u64) {
        self.messages.remove(&arrival);
    }
}
